COLORS={'CB_BODY': [0.87, 0.89, 0.87, 1], 'CB_ROOF': [0.37, 0.48, 0.54, 1], 'CB_GLAZING': [0.09, 0.14, 0.19, 1], 'CB_ACCENT': [0.19, 0.43, 0.58, 1]}
ANCHORS={'ANCHOR_LABEL': [0, 3.78, 0], 'ANCHOR_STATUS': [1.95, 2.8, 1.94], 'ANCHOR_SIGN': [1.3, 2.75, 1.82]}
# Blender 4.2+; built-in modules only. Run: blender -b -P source.py
import bpy, json, zlib, base64, os, math
from mathutils import Vector
bpy.ops.object.select_all(action='SELECT'); bpy.ops.object.delete(use_global=False)
data=json.loads(zlib.decompress(base64.b85decode(PACKED)).decode())
colors=COLORS
for group,meshdata in data.items():
    # GLB X,Y,Z -> Blender X,-Z,Y (exported with +Y up)
    verts=[(v[0],-v[2],v[1]) for v in meshdata['v']]
    mesh=bpy.data.meshes.new(group);mesh.from_pydata(verts,[],meshdata['f']);mesh.update()
    obj=bpy.data.objects.new(group,mesh);bpy.context.collection.objects.link(obj)
    mat=bpy.data.materials.new(group);mat.diffuse_color=(*colors[group][:3],1.0);mat.use_nodes=True
    bsdf=mat.node_tree.nodes.get('Principled BSDF');bsdf.inputs['Base Color'].default_value=(*colors[group][:3],1);bsdf.inputs['Metallic'].default_value=0.08 if group=='CB_BODY' else (0.55 if group in ('CB_ROOF','CB_ACCENT') else 0.02);bsdf.inputs['Roughness'].default_value=0.72 if group=='CB_BODY' else (0.25 if group=='CB_GLAZING' else 0.48)
    mesh.materials.append(mat)
for name,loc in ANCHORS.items():
    ob=bpy.data.objects.new(name,None);bpy.context.collection.objects.link(ob);ob.location=(loc[0],-loc[2],loc[1]);ob.empty_display_type='PLAIN_AXES'
bpy.ops.object.select_all(action='SELECT');bpy.context.view_layer.objects.active=next(o for o in bpy.context.scene.objects if o.type=='MESH')
bpy.ops.export_scene.gltf(filepath=os.path.join(os.path.dirname(os.path.abspath(__file__)),'control-building.glb'),export_format='GLB',export_yup=True,export_apply=True,export_cameras=False,export_lights=False)
print('GLB exported; validate output separately')
